// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        if (amount > 0) {
            c.deposit{value: amount}();
        } else {
            c.deposit{value: 0}();
        }

        uint256 beforeBal = address(c).balance;

        vm.prank(actor);
        c.withdrawAll();

        assertTrue(address(c).balance <= beforeBal);
    }
}
